    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint256 payAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (payAmount)); require(payAmount <= 1000000000000000000000000000000);
        require(payAmount > 0);
        require(address(this).balance >= payAmount);

        uint256 balBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 valueBefore = c.value(); if (__ESBMC_reverted()) return;

        c.getTokens{value: payAmount}(); if (__ESBMC_reverted()) return;

        assert(c.balanceOf(address(this)) == balBefore + valueBefore && c.blacklist(address(this)));
    }
}

