// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    XBORNID c;

    function setUp() public {
        c = new XBORNID();
    }

    function _run(uint256 payAmount) internal {
        payAmount = bound(payAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(payAmount > 0);
        vm.assume(address(this).balance >= payAmount);
        uint256 balBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 valueBefore;
        try c.value() returns (uint256 __r) { valueBefore = __r; } catch { return; }
        try c.getTokens{value: payAmount}() {} catch { return; }
        assertTrue(c.balanceOf(address(this)) == balBefore + valueBefore && c.blacklist(address(this)));
    }

    function testFuzz_run(uint256 payAmount) public {
        _run(payAmount);
    }

    receive() external payable {}
}
